 <!DOCTYPE html>
 <html lang="en">
 <head>
   <meta charset="UTF-8">
   <meta name="viewport" content="width=device-width, initial-scale=1.0">
   <title>Support Contact Form</title>
   <style>
     :root {
       color-scheme: light;
       --background: #f4f7fb;
       --text: #172033;
       --muted: #5f6f89;
       --border: #c9d4e5;
       --border-strong: #627491;
       --primary: #155eef;
       --primary-dark: #0f48b8;
       --danger: #b42318;
       --success: #027a48;
       --focus: #102a56;
       --shadow: 0 24px 70px rgba(23, 32, 51, 0.12);
     }

     * {
       box-sizing: border-box;
     }

     body {
