       color: var(--text);
       background:
         radial-gradient(circle at top left, rgba(21, 94, 239, 0.16), transparent 34rem),
         linear-gradient(135deg, #f8fbff 0%, var(--background) 100%);
     }

     .skip-link {
       position: fixed;
       top: 1rem;
