 <!DOCTYPE html>
 <html lang="en">
 <head>
   <meta charset="UTF-8">
   <meta name="viewport" content="width=device-width, initial-scale=1.0">
   <title>Support Contact Form</title>
   <style>
     :root {
       color-scheme: light;
       --background: #f4f7fb;
       --text: #172033;
       --muted: #5f6f89;
       --border: #c9d4e5;
       --border-strong: #627491;
       --primary: #155eef;
       --primary-dark: #0f48b8;
       --danger: #b42318;
       --success: #027a48;
       --focus: #102a56;
       --shadow: 0 24px 70px rgba(23, 32, 51, 0.12);
     }

     * {
       box-sizing: border-box;
     }

     body {
       margin: 0;
       min-height: 100vh;
       font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       color: var(--text);
       background:
         radial-gradient(circle at top left, rgba(21, 94, 239, 0.16), transparent 34rem),
         linear-gradient(135deg, #f8fbff 0%, var(--background) 100%);
     }

     .skip-link {
       position: fixed;
       top: 1rem;
       left: 1rem;
       z-index: 10;
       transform: translateY(-200%);
       padding: 0.75rem 1rem;
       border-radius: 0.75rem;
       color: #ffffff;
       background: var(--primary);
       font-weight: 700;
     }

     .skip-link:focus {
       transform: translateY(0);
       outline: 3px solid var(--focus);
       outline-offset: 3px;
     }

     .page-shell {
       display: grid;
       place-items: center;
       min-height: 100vh;
       padding: 2rem 1rem;
     }

     .support-card {
       width: min(100%, 44rem);
       padding: clamp(1.5rem, 4vw, 3rem);
       border: 1px solid rgba(201, 212, 229, 0.8);
       border-radius: 2rem;
       background: rgba(255, 255, 255, 0.92);
       box-shadow: var(--shadow);
     }

     .support-intro {
       margin-bottom: 2rem;
     }

     .eyebrow {
       margin: 0 0 0.75rem;
       color: var(--primary);
       font-size: 0.8rem;
       font-weight: 800;
       letter-spacing: 0.12em;
       text-transform: uppercase;
     }

     h1 {
       margin: 0;
       font-size: clamp(2rem, 6vw, 3.25rem);
       line-height: 1.05;
       letter-spacing: -0.04em;
     }

     .intro-text,
     .required-note,
     .helper-text,
     .optional-text,
     .form-status {
       color: var(--muted);
     }

     .intro-text {
       max-width: 36rem;
       margin: 1rem 0 0;
       font-size: 1.05rem;
       line-height: 1.6;
     }

     .contact-form {
       display: grid;
       gap: 1.25rem;
     }

     .required-note {
       margin: 0;
       font-size: 0.95rem;
     }

     .form-field {
       display: grid;
       gap: 0.5rem;
     }

     label {
       font-weight: 700;
     }

     input {
       width: 100%;
       min-height: 3.25rem;
       padding: 0.75rem 1rem;
       border: 1px solid var(--border);
       border-radius: 0.9rem;
       color: var(--text);
       background: #ffffff;
       font: inherit;
       transition: border-color 160ms ease, box-shadow 160ms ease;
     }

     input:hover {
       border-color: var(--border-strong);
     }

     input:focus,
     button:focus {
       outline: 3px solid var(--focus);
       outline-offset: 3px;
     }

     input[aria-invalid="true"] {
       border-color: var(--danger);
     }

     .helper-text,
     .error-text,
     .form-status {
       margin: 0;
       font-size: 0.95rem;
       line-height: 1.5;
     }

     .error-text {
       color: var(--danger);
       font-weight: 600;
     }

     button {
       justify-self: start;
       min-height: 3.25rem;
       padding: 0.85rem 1.35rem;
       border: 0;
       border-radius: 999px;
       color: #ffffff;
       background: var(--primary);
       font: inherit;
       font-weight: 800;
       cursor: pointer;
       box-shadow: 0 12px 28px rgba(21, 94, 239, 0.26);
       transition: background 160ms ease, transform 160ms ease;
     }

     button:hover {
       background: var(--primary-dark);
       transform: translateY(-1px);
     }

     button:active {
       transform: translateY(0);
     }

     .form-status.success {
       color: var(--success);
       font-weight: 700;
     }

     @media (max-width: 36rem) {
       .support-card {
         border-radius: 1.35rem;
       }

       button {
         width: 100%;
       }
     }

     @media (forced-colors: active) {
       .support-card,
       input,
       button {
         border: 1px solid CanvasText;
       }

       button {
         box-shadow: none;
       }
     }
   </style>
 </head>
 <body>
   <a class="skip-link" href="#main-content">Skip to main content</a>

   <main id="main-content" class="page-shell">
     <section class="support-card" aria-labelledby="support-title">
       <div class="support-intro">
         <p class="eyebrow">Support</p>
         <h1 id="support-title">Contact our support team</h1>
         <p class="intro-text">Tell us how to reach you and a support specialist will follow up soon.</p>
       </div>

       <form id="support-form" class="contact-form" novalidate>
         <p class="required-note"><span aria-hidden="true">*</span> Required fields</p>

         <div class="form-field">
           <label for="full-name">Full name <span aria-hidden="true">*</span></label>
           <input
             id="full-name"
             name="fullName"
             type="text"
             autocomplete="name"
             required
           >
         </div>

         <div class="form-field">
           <label for="email">Email address <span aria-hidden="true">*</span></label>
           <input
             id="email"
             name="email"
             type="email"
             autocomplete="email"
             required
           >
         </div>

         <div class="form-field">
           <label for="phone">Phone number <span class="optional-text">(optional)</span></label>
           <input
             id="phone"
             name="phone"
             type="tel"
             autocomplete="tel"
             inputmode="tel"
             aria-describedby="phone-help"
           >
           <p id="phone-help" class="helper-text">Use this format: +1 555 123 4567, including country code when outside your country.</p>
         </div>

         <button type="submit">Send request</button>

         <p id="form-status" class="form-status" aria-live="polite"></p>
       </form>
     </section>
   </main>

   <script>
     const form = document.querySelector("#support-form");
     const statusMessage = document.querySelector("#form-status");

     const fields = [
       {
         input: document.querySelector("#full-name"),
         message: "Error: Enter your full name."
       },
       {
         input: document.querySelector("#email"),
         message: "Error: Enter a valid email address, like name@example.com."
       }
     ];

     function setFieldError(input, message) {
       const errorId = `${input.id}-error`;
       let error = document.querySelector(`#${errorId}`);

       if (!error) {
         error = document.createElement("p");
         error.id = errorId;
         error.className = "error-text";
         input.insertAdjacentElement("afterend", error);
       }

       error.textContent = message;
       input.setAttribute("aria-invalid", "true");
       input.setAttribute("aria-describedby", errorId);
     }

     function clearFieldError(input) {
       const error = document.querySelector(`#${input.id}-error`);
       const describedBy = input.getAttribute("aria-describedby");

       if (error) {
         error.remove();
       }

       input.removeAttribute("aria-invalid");

       if (describedBy === `${input.id}-error`) {
         input.removeAttribute("aria-describedby");
       }
     }

     form.addEventListener("submit", (event) => {
       event.preventDefault();
       statusMessage.textContent = "";
       statusMessage.className = "form-status";

       let firstInvalidField = null;

       fields.forEach(({ input, message }) => {
         if (!input.validity.valid) {
           setFieldError(input, message);
           firstInvalidField ||= input;
         } else {
           clearFieldError(input);
         }
       });

       if (firstInvalidField) {
         firstInvalidField.focus();
         return;
       }

       form.reset();
       fields.forEach(({ input }) => clearFieldError(input));
       statusMessage.textContent = "Thanks. Your support request has been sent.";
       statusMessage.classList.add("success");
     });

     fields.forEach(({ input }) => {
       input.addEventListener("input", () => {
         if (input.validity.valid) {
           clearFieldError(input);
         }
       });
     });
   </script>
 </body>
 </html>

